+
+tasks.named("dependencyLicenses").configure {
+  mapping from: /jackson-.*/, to: 'jackson'
+}
+
+shadowJar {
+  exclude { element ->
+    element.file == null && element.path.endsWith("FilteringParserDelegate.class")
