+        assertThat(V_7_2_0.onOrAfter(V_7_2_0), is(true));
+        assertThat(V_8_0_0.onOrAfter(V_7_2_0), is(true));
+
+        assertThat(V_7_2_0, is(lessThan(V_8_0_0)));
